/* ---------- apply the checks to the directory ---------- */
const VER_ST = {v:["✓ 2027 date","Confirmed for the 2027 cycle on the university's own page","dv-v"], p:["2026 pattern","The university's own 2026-cycle dates; the 2027 dates are not out yet","dv-p"], s:["Secondary source","From a consultancy or aggregator; confirm on the official page","dv-s"]};
const LAC_WIN = "ED I ~1–15 Nov · ED II / RD ~1–15 Jan 2027 (typical; confirm)";
U_RAW.forEach(r => {
  const v = VER[r[0]];
  if (!v) { if (SEG[r[0]] === "lac" && /^u_/.test(r[0])) { r[10] = LAC_WIN; r[11] = "2026-12-18"; r[12] = "2027-01-01"; } return; }
  if (v.win) r[10] = v.win;
  if (v.sug !== undefined) r[11] = v.sug;
  if (v.fin !== undefined) r[12] = v.fin;
  if (v.req !== undefined) r[8] = v.req;
  if (v.rule) r[9] = v.rule;
});
